import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Solver().solve(1, in, out);
        out.close();
    }

    static class Solver {
        long mod = 1000000007;
        long INF = (long) 1e18 + 1;
        long[][] nCr = new long[100][100];

        long f(long p, int a, int b, int c, int d) {
            p = p * nCr[a][b] % mod;
            p = p * nCr[c][d] % mod;
            return p;
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int K = in.nextInt();
            for (int i = 0; i < 100; i++) {
                for (int j = 0; j <= i; j++) {
                    if (j == 0 || j == i) nCr[i][j] = 1;
                    else nCr[i][j] = (nCr[i - 1][j] + nCr[i - 1][j - 1]) % mod;
                }
            }
            int cnt1 = 0, cnt2 = 0;
            for (int i = 0; i < n; i++) {
                if (in.nextInt() == 50) cnt1++;
                else cnt2++;
            }
            long[][][] dist = new long[200][200][2];
            long[][][] dp = new long[200][200][2];
            for (int i = 0; i < 200; i++) {
                for (int j = 0; j < 200; j++) {
                    Arrays.fill(dist[i][j], INF);
                }
            }
            dist[0][0][0] = 0;
            dp[0][0][0] = 1;
            ArrayDeque<State> q = new ArrayDeque<>();
            q.add(new State(0, 0, 0));
            while (!q.isEmpty()) {
                State cur = q.poll();
                int x = cur.x;
                int y = cur.y;
                int z = cur.z;
                long d = dist[x][y][z];
                int limX = (z == 0) ? cnt1 - x : x;
                int limY = (z == 0) ? cnt2 - y : y;
                for (int a = 0; a <= limX; a++) {
                    for (int b = 0; b <= limY; b++) {
                        if (a + b == 0) continue;
                        if (a * 50 + b * 100 > K) break;
                        int nx = (z == 0) ? x + a : x - a;
                        int ny = (z == 0) ? y + b : y - b;
                        int nz = z ^ 1;
                        if (dist[nx][ny][nz] >= d + 1) {
                            long add = f(dp[x][y][z], limX, a, limY, b);
                            if (dist[nx][ny][nz] > d + 1) {
                                dist[nx][ny][nz] = d + 1;
                                q.add(new State(nx, ny, nz));
                            }
                            dp[nx][ny][nz] = (dp[nx][ny][nz] + add) % mod;
                        }
                    }
                }
            }
            if (dist[cnt1][cnt2][1] == INF) out.println(-1);
            else out.println(dist[cnt1][cnt2][1]);
            out.println(dp[cnt1][cnt2][1]);
        }

        static class State {
            int x, y, z;

            State(int x, int y, int z) {
                this.x = x;
                this.y = y;
                this.z = z;
            }
        }
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new UnknownError();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new UnknownError();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuffer res = new StringBuffer();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
